    @Override void observe(ActionOracleHarness h,RunResult r,long pc)throws Exception {
        super.observe(h,r,pc);int n=-1;
        if(pc==0x164a0e||pc==0x157586)n=3;else if(pc==0x14ef76)n=4;else if(pc==0x12006e||pc==0x130afe||pc==0x139192||pc==0x136994)n=1;
        if(n>=0){JsonObject c=new JsonObject();c.addProperty("address",Long.toHexString(pc));c.addProperty("return",Long.toHexString(h.pointer(h.sp())));JsonArray args=new JsonArray();for(int i=0;i<n;i++)args.add(h.word(h.sp()+4+i*2));c.add("arguments",args);c.addProperty("draws",r.draws);nativeCalls.add(c);}
    }
