    void actualSetup(ActionOracleHarness h,int member,boolean combat,RunResult r){setup(h,warriors(foundation),crate(foundation),member,combat?1:0,r);nativeCalls=new JsonArray();h.write(0x442562,array(foundation.getAsJsonArray("party_buffs")));h.write(0x43788a,array(foundation.getAsJsonArray("psi_memory")));ByteBuffer b=ByteBuffer.allocate(800);for(JsonElement e:foundation.getAsJsonArray("ammunition"))b.putInt(e.getAsInt());h.write(0x42dbe4,b.array());JsonObject work=foundation.getAsJsonObject("weapon_work");h.value(0x453776,2,work.get("sound").getAsInt());h.value(0x4537f0,2,work.get("weapon_armor_filter").getAsInt());h.value(0x45375a,2,work.get("ammunition_armor_filter").getAsInt());h.value(0x45365c,2,foundation.get("loaded_item_field32").getAsInt());if(combat)h.value(0x448aa0+member*3138+0x40,2,3);r.draws=foundation.getAsJsonObject("random").get("draws").getAsInt();}
